  formatReviewDate(value){return new Date(value).toLocaleDateString('es-MX',{day:'numeric',month:'short'});}
  renderReview(){const schedule=reviewSchedule(this.progress),allowance=this.reviewAllowance(),due=reviewItemsForSession(this.progress,allowance.remaining),available=Math.min(schedule.due.length,allowance.remaining),percent=Math.round(allowance.completed/allowance.limit*100);this.reviewMode=false;this.shell(`<section class="jp-simple-view jp-review-dashboard"><span class="eyebrow">REPETICIÓN ESPACIADA</span><h1>Repaso de hoy</h1><p>Cada elemento vuelve después de 1, 3, 7, 14 y 30 días. Si fallas, vuelve antes; si aciertas, el intervalo crece.</p><div class="jp-srs-steps"><span>1 día</span><span>3 días</span><span>7 días</span><span>14 días</span><span>30 días</span></div><section class="jp-daily-review-limit"><div><strong>${allowance.completed} de ${allowance.limit}</strong><span>tarjetas repasadas hoy</span></div><div class="jp-progress"><i style="width:${percent}%"></i></div><small>Puedes cambiar este límite en Cuenta → Ajustes.</small></section>${due.length?`<section class="jp-review-ready"><strong>${available}</strong><div><h2>Repaso preparado</h2><p>Las respuestas permanecen ocultas hasta comenzar para que el repaso mida tu memoria de verdad.</p></div></section><button class="primary" data-jp-action="start-review">Comenzar repaso</button>`:`<div class="jp-empty-state"><b>✓</b><h2>${allowance.remaining?'Estás al día':'Límite diario completado'}</h2><p>${allowance.remaining?'Cuando corresponda, se preparará una nueva sesión.':'Buen trabajo. Puedes continuar aprendiendo contenido nuevo sin acumular más repasos hoy.'}</p></div>`}<button data-jp-route="course">Volver al mapa</button></section>`,'Repaso');}
