  async playKeyAudio(key,mode='normal',notify=true,onState=null){this.stopPlayback();const version=this.playbackVersion,path=this.audioManifest[key];if(!String(key||'').trim()){onState?.('error');return false;}const repeat=mode==='repeat'?3:1,rate=mode==='slow'?.65:1;let useTts=!path,announced=false;for(let round=0;round<repeat;round++){if(version!==this.playbackVersion)return false;let ok=useTts?false:await this.playFile(path,rate,onState);if(version!==this.playbackVersion)return false;if(!ok){useTts=true;if(notify&&!announced){this.showToast('Esta frase se reproduce con voz sintetizada porque su grabación no está disponible.');announced=true;}ok=await this.speakTts(key,rate,onState);}if(!ok||version!==this.playbackVersion)return false;}return true;}
  playFile(path,rate,onState=null){return new Promise(resolve=>{this.audio.pause();this.audio.src=this.url(`library/courses/${this.definition.directory}/${path}`);this.audio.playbackRate=rate;let finished=false;const done=ok=>{if(finished)return;finished=true;if(this.finishPlayback===done)this.finishPlayback=null;resolve(ok);};this.finishPlayback=done;onState?.('loading');this.audio.onplaying=()=>onState?.('playing');this.audio.onended=()=>done(true);this.audio.onerror=()=>done(false);this.audio.play().catch(()=>done(false));});}
  soundEffect(correct){if(!this.feedbackSounds)return;try{const context=new(window.AudioContext||window.webkitAudioContext)(),osc=context.createOscillator(),gain=context.createGain();osc.frequency.value=correct?660:190;gain.gain.setValueAtTime(.08,context.currentTime);gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+.18);osc.connect(gain).connect(context.destination);osc.onended=()=>context.close?.();osc.start();osc.stop(context.currentTime+.18);}catch{}}
  showToast(text){let toast=this.root.querySelector('.jp-toast');if(!toast){toast=document.createElement('div');toast.className='jp-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');this.root.append(toast);}toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400);}
  handleClick(event){const keyboardInput=event.target.closest('[data-jp-keyboard-input]'),answer=event.target.closest('[data-jp-answer]'),block=event.target.closest('[data-jp-block]'),virtualKey=event.target.closest('[data-jp-virtual-key]'),keyboardPage=event.target.closest('[data-jp-keyboard-page]'),lesson=event.target.closest('[data-jp-lesson]'),unit=event.target.closest('[data-jp-unit]'),routeButton=event.target.closest('[data-jp-route]'),wordAudio=event.target.closest('[data-jp-word-speak]'),audio=event.target.closest('[data-jp-audio]'),action=event.target.closest('[data-jp-action]');if(keyboardInput&&this.usesMobileCourseKeyboard()){const target=keyboardInput.dataset.jpKeyboardTarget||keyboardInput.id;if(this.keyboardTarget!==target)return this.openCourseKeyboard(target);return this.captureKeyboardCursor(event);}if(answer)return this.chooseAnswer(answer.dataset.jpAnswer);if(block)return this.chooseBlock(block.dataset.jpBlock,Number(block.dataset.jpBlockIndex));if(virtualKey)return this.applyKeyboardInput(virtualKey.dataset.jpKeyboardTarget,virtualKey.dataset.jpVirtualKey,virtualKey.dataset.jpDialogueIndex??'');if(keyboardPage)return this.setKeyboardPage(keyboardPage.dataset.jpKeyboardPage,keyboardPage.dataset.jpKeyboardTarget);if(lesson)return this.navigate('lesson',lesson.dataset.jpLesson);if(unit)return this.navigate('unit',unit.dataset.jpUnit);if(routeButton)return this.navigate(routeButton.dataset.jpRoute);if(wordAudio)return this.speakGlossaryWord(wordAudio.dataset.jpWordSpeak,wordAudio);if(audio)return this.playAudio(audio.dataset.jpAudio,audio.dataset.jpAudioSource||'prompt',audio);if(!action)return;const name=action.dataset.jpAction;if(name==='cancel-speech'){this.cancelSpeech();this.renderActivity();return;}if(name==='retry-load'){this.stop();this.course=null;this.units.clear();this.start();}else if(name==='check')this.check();else if(name==='continue')this.continue();else if(name==='start-review')this.startReview();else if(name==='toggle-keyboard'){const target=action.dataset.jpKeyboardTarget;if(this.keyboardTarget===target){this.keyboardTarget='';this.keyboardSelection=null;this.renderActivity();}else this.openCourseKeyboard(target);}else if(name==='hide-keyboard'){this.keyboardTarget='';this.keyboardSelection=null;this.keyboardShift=false;this.renderActivity();}else if(name==='toggle-keyboard-shift'){this.keyboardShift=!this.keyboardShift;this.refreshCourseKeyboard();}else if(name==='keyboard-submit'){if(this.canSubmitCurrentActivity()){this.keyboardTarget='';this.keyboardSelection=null;this.keyboardShift=false;this.check();}else this.showToast('Escribe una respuesta antes de comprobarla.');}else if(name==='speak')this.startSpeech(action.dataset.jpDialogueIndex??'');else if(name==='skip-speaking'){this.answers[this.lesson.activities[this.activityIndex].id]='__skipped__';this.check();}else if(name==='toggle-pinyin'){const activity=this.lesson.activities[this.activityIndex];this.pinyinVisible.has(activity.id)?this.pinyinVisible.delete(activity.id):this.pinyinVisible.add(activity.id);this.renderActivity();}else if(name==='clear-answer'){const activity=this.lesson.activities[this.activityIndex];delete this.answers[activity.id];delete this.blockSelections[activity.id];this.renderActivity();}else if(name==='hint')this.showToast(this.lesson.activities[this.activityIndex].explanation);else if(name==='retry')this.retryErrors(action.dataset.jpRetry);else if(name==='leave-lesson'){if(this.reviewMode){this.reviewMode=false;this.navigate('review');}else this.navigate('unit',this.unit.id);}else if(name==='stories'){this.stop();history.replaceState(null,'',location.pathname+location.search);this.onStories?.();}else if(name==='manga-reveal'){const card=this.currentMangaCard();if(card&&!this.mangaState.revealedIds.includes(card.id)){this.mangaState.revealedIds.push(card.id);this.saveMangaState();}this.renderManga();}else if(name==='manga-save'){const card=this.currentMangaCard();if(card&&!this.mangaState.savedIds.includes(card.id)){this.mangaState.savedIds.push(card.id);this.saveMangaState();this.showToast('Frase guardada para volver a verla.');}this.renderManga();}else if(name==='manga-next'){this.mangaState.currentIndex=Number(this.mangaState.currentIndex||0)+1;this.saveMangaState();this.renderManga();}else if(name==='exit'){this.stop();history.replaceState(null,'',location.pathname+location.search);this.onExit?.();}}
